import torch
import torch.nn as nn
from torch_geometric.nn import GCNConv, GATConv, SAGEConv, GINConv
from torch_geometric.nn.models import GCN, GAT, GraphSAGE, GIN

BASELINES_CONFIG = {
    "GCN": {
        "param_count": "Depends on hidden_dim and layers",
        "paper": "Kipf & Welling, Semi-Supervised Classification with GCN, ICLR 2017",
        "source": "torch_geometric.nn.GCNConv",
    },
    "GAT": {
        "param_count": "Depends on hidden_dim, heads, and layers",
        "paper": "Velickovic et al., Graph Attention Networks, ICLR 2018",
        "source": "torch_geometric.nn.GATConv",
    },
    "GraphSAGE": {
        "param_count": "Depends on hidden_dim and layers",
        "paper": "Hamilton et al., Inductive Representation Learning, NeurIPS 2017",
        "source": "torch_geometric.nn.SAGEConv",
    },
    "GIN": {
        "param_count": "Depends on hidden_dim and layers",
        "paper": "Xu et al., How Powerful are GNNs?, ICLR 2019",
        "source": "torch_geometric.nn.GINConv",
    },
}

def get_baselines(num_classes, device='cuda') -> dict:
    baselines = {}

    # GCN
    class GCNModel(nn.Module):
        def __init__(self, input_dim, hidden_dim, num_classes):
            super(GCNModel, self).__init__()
            self.conv1 = GCNConv(input_dim, hidden_dim)
            self.conv2 = GCNConv(hidden_dim, num_classes)

        def forward(self, x, edge_index):
            x = self.conv1(x, edge_index).relu()
            x = self.conv2(x, edge_index)
            return x

    baselines["GCN"] = GCNModel(input_dim=1433, hidden_dim=16, num_classes=num_classes).to(device)

    # GAT
    class GATModel(nn.Module):
        def __init__(self, input_dim, hidden_dim, num_classes, heads=8):
            super(GATModel, self).__init__()
            self.conv1 = GATConv(input_dim, hidden_dim, heads=heads)
            self.conv2 = GATConv(hidden_dim * heads, num_classes, heads=1)

        def forward(self, x, edge_index):
            x = self.conv1(x, edge_index).relu()
            x = self.conv2(x, edge_index)
            return x

    baselines["GAT"] = GATModel(input_dim=1433, hidden_dim=8, num_classes=num_classes).to(device)

    # GraphSAGE
    class GraphSAGEModel(nn.Module):
        def __init__(self, input_dim, hidden_dim, num_classes):
            super(GraphSAGEModel, self).__init__()
            self.conv1 = SAGEConv(input_dim, hidden_dim)
            self.conv2 = SAGEConv(hidden_dim, num_classes)

        def forward(self, x, edge_index):
            x = self.conv1(x, edge_index).relu()
            x = self.conv2(x, edge_index)
            return x

    baselines["GraphSAGE"] = GraphSAGEModel(input_dim=1433, hidden_dim=16, num_classes=num_classes).to(device)

    # GIN
    class GINModel(nn.Module):
        def __init__(self, input_dim, hidden_dim, num_classes):
            super(GINModel, self).__init__()
            nn1 = nn.Sequential(nn.Linear(input_dim, hidden_dim), nn.ReLU(), nn.Linear(hidden_dim, hidden_dim))
            nn2 = nn.Sequential(nn.Linear(hidden_dim, hidden_dim), nn.ReLU(), nn.Linear(hidden_dim, num_classes))
            self.conv1 = GINConv(nn1)
            self.conv2 = GINConv(nn2)

        def forward(self, x, edge_index):
            x = self.conv1(x, edge_index).relu()
            x = self.conv2(x, edge_index)
            return x

    baselines["GIN"] = GINModel(input_dim=1433, hidden_dim=16, num_classes=num_classes).to(device)

    return baselines
